insert into public.desk_rules (rule_id, title, purpose, mechanism, owner_paths, status, verdict, ruling_summary, growth_cost, ruin_risk_reduction, statistics_note, gaming_analysis, interactions, needs_david, ruling_file, ruling_date, next_review_date) values
  ('edge-max-stake', 'Edge-scaled max stake (proven-edge growth)', 'Stops an unbounded requested size (the $200 Miami bet on a $490 book) while letting a proven edge compound.', '`private.edge_max_stake`: unproven (n < 10 or LCB <= 0) gets the starter; proven gets max(starter, min(book x 0.5 x LCB / sd^2, starter x 2^(1 + (n - 10) / 5))). LCB = mean - sd/sqrt(n) of return on stake. `sized_notional = min(requested, max_stake, cash)`.', array['supabase/schemas/22_edge_scaled_stake.sql', 'supabase/schemas/23_edge_stake_reason.sql', 'supabase/schemas/36_court_rulings.sql']::text[], 'in_force', 'amend', 'Uphold the proven-edge formula at 1 sigma. Amend so n and the moments include discounted backtest evidence (backtest-evidence-credit) and so the cap is multiplied by the steward drawdown scale instead of per-thesis loss halving. Amendment: n_eff = n_live + min(0.5 x n_backtest, 20), with the backtest mean haircut 50%. The cap is multiplied by the scale from `private.steward_drawdown`. The starter is a share of current book.', 'None vs current; raises growth (loss halving removed).', 'Bounds every entry; half-Kelly on LCB.', 'The 1-sigma LCB with continuous monitoring falsely marks a zero-edge thesis proven in 47-69% of MC paths within a year. A 2-sigma bound cuts that to 9-23%, but it delays real proof (QUANTANAMO at Sharpe 0.2: 14 -> 38 trades) and cuts BANDIT''s median growth at Sharpe 0.2 from 28.4x to 9.8x. With drawdown scaling as the backstop, false proofs cost little: P(DD50) at zero edge is 9.3% at 1 sigma vs 4.7% at 2 sigma.', 'A steward could inflate `requested` to get more size. That no longer helps: the cap binds, and the multiplier that rewarded inflation is struck (see confidence-multiplier). Only closed, priced, non-paper trades count, so the n gate can''t be padded with paper trades.', 'starter-stake, drawdown-scaling, backtest-evidence-credit, confidence-multiplier, entry-cap-snapshot.', false, 'docs/rules/edge-max-stake.md', '2026-09-26'::date, '2026-10-26'::date),
  ('starter-stake', 'Starter stake for unproven theses', 'Lets an unproven thesis trade (learning comes from trade count, not size) without a big loss before there is evidence.', 'Was fixed dollars: QUANTANAMO $250, ODDSBORNE $15, BANDIT 0.10 SOL. Now a share of the current book: 4.545% / 5.418% / 5.546%. That is today''s values re-expressed, so nothing changes at today''s book.', array['supabase/schemas/22_edge_scaled_stake.sql', 'supabase/schemas/36_court_rulings.sql']::text[], 'in_force', 'amend', 'Amend (shipped): book share, not fixed dollars. The starter LEVEL (vol-normalized v) is a risk-budget choice for David, so it is not shipped. See docs/rules/SIMULATION.md for the options. Amendment: starter = share x current book equity, shares QUANTANAMO 0.04545, ODDSBORNE 0.05418, BANDIT 0.05546 (= the 2026-09-26 dollar starters / that day''s book).', 'None today; compounds after gains.', 'Shrinks with the book: ODDSBORNE MC ruin 10.1% -> 0.1%.', 'The starter should be calibrated to stake volatility, not a flat %. A vol-normalized starter, stake = v x book / sd(return on stake), gives every steward the same book risk per unproven bet.', 'With a flat %, the steward whose instruments are most volatile gets the most book risk per bet (ODDSBORNE). Vol-normalizing removes that tilt.', 'edge-max-stake, drawdown-scaling.', true, 'docs/rules/starter-stake.md', '2026-09-26'::date, '2026-10-10'::date),
  ('loss-streak-halving', 'Per-thesis consecutive-loss halving (x0.5 per loss, floor x0.25)', 'Meant to cut size when a thesis is failing.', '`private.edge_max_stake` multiplied the cap by 0.5^min(loss_streak, 2).', array['supabase/schemas/23_edge_stake_reason.sql', 'supabase/schemas/36_court_rulings.sql']::text[], 'in_force', 'strike', 'Strike. Replace with steward-level drawdown scaling (drawdown-scaling). Amendment: Removed from `private.edge_max_stake`. `loss_streak` stays in the stats for information.', 'Removing it raises growth (BANDIT median +14% at Sharpe 0.1).', 'Replaced by drawdown scaling, which has equal or lower P(DD50) at the same starter.', 'Loss streaks carry no information: BANDIT P(loss | previous loss) 0.53 vs P(loss) 0.51, lag-1 autocorrelation 0.004 over 35 trades. The edge estimate (LCB) already absorbs the losses. Halving punishes the same evidence twice.', 'It''s per thesis, so a steward escapes it by registering a new thesis (the new-thesis escape). It also rewards cutting a loser early to reset the streak, whatever the thesis''s real invalidation says.', 'drawdown-scaling, new-thesis-escape.', false, 'docs/rules/loss-streak-halving.md', '2026-09-26'::date, '2026-12-26'::date),
  ('drawdown-scaling', 'Steward-level drawdown scaling', 'Cuts risk when the BOOK is in trouble (the thing that can actually be ruined), not when one thesis label had a streak.', 'scale = 1.0 at <= 10% below the steward''s closing high-water mark, falling linearly to 0.5 at >= 40%. The HWM is the max of each UTC day''s last book observation, used because intraday entry-time snapshots include double-count artifacts. It multiplies every thesis''s cap, proven or not. `private.steward_drawdown`.', array['supabase/schemas/36_court_rulings.sql']::text[], 'proposed', 'amend', 'Enact. Amendment: New rule (migration 36).', '0 inside a 10% drawdown; x0.5 at worst.', 'BANDIT P(DD50) 35.9% -> 9.3%; ODDSBORNE ruin 7.4% -> 0.1% (zero edge).', 'Uses the book path, which is the actual ruin variable. No thesis-level noise. The 10% dead band sits above normal noise (QUANTANAMO''s worst close-to-close drawdown is 16%; BANDIT''s intraday swings reach 30%).', 'Steward-wide, so it can''t be escaped with a new thesis. Deposits would reset the HWM mechanics; none have happened. A deposit should be recorded as a flow before this rule reads it.', 'Replaces loss-streak-halving; closes new-thesis-escape; multiplies edge-max-stake.', false, 'docs/rules/drawdown-scaling.md', '2026-09-26'::date, '2026-10-26'::date),
  ('new-thesis-escape', 'New-thesis escape from a loss-reduced cap', 'The problem: per-thesis halving could be escaped by registering a new thesis. The first fix (steward-wide cap on every unproven thesis, #97) pinned QUANTANAMO themes at $62.50 and was reverted (#98).', 'Resolved structurally. Loss halving is struck, and the only loss response is steward-wide drawdown scaling, which applies to every thesis, new or old. A new thesis gets the starter x the steward''s drawdown scale, the same as any unproven thesis.', array['supabase/schemas/34_revert_steward_wide_starter.sql', 'supabase/schemas/36_court_rulings.sql']::text[], 'in_force', 'strike', 'Strike the problem at its root (no per-thesis punishment exists to escape). No separate rule needed. Amendment: None beyond loss-streak-halving and drawdown-scaling.', 'None.', 'Via drawdown-scaling.', 'Punishing unrelated theses for one thesis''s streak treats noise as signal.', 'Remaining gap (David): for QUANTANAMO, a new thesis''s confidence starts at the steward''s own stated number, so a new thesis stated at >= 80 passes the autonomous gate with zero evidence. See quantanamo-80-gate.', 'loss-streak-halving, drawdown-scaling, quantanamo-80-gate.', true, 'docs/rules/new-thesis-escape.md', '2026-09-26'::date, '2026-10-26'::date),
  ('confidence-multiplier', 'Half-Kelly outcome multiplier on the requested size', 'Scaled requested size by a half-Kelly estimate from hit rate and avg win/loss (0.5 when n < 5, 0.25 with no edge).', '`sized_notional = min(requested x multiplier, max_stake, cash)`. Now `min(requested, max_stake, cash)`. The multiplier is still returned for information.', array['supabase/schemas/11_outcome_rescore_sizing.sql', 'supabase/schemas/22_edge_scaled_stake.sql', 'supabase/schemas/36_court_rulings.sql']::text[], 'in_force', 'strike', 'Strike from sizing. Keep reporting it. Amendment: guidance: sized_notional = min(requested, max_stake, spendable cash). QUANTANAMO requested % is no longer multiplied (scheduled-run prompt). The retired workers/research mirror is left alone.', 'Raises honest sizes up to 2x (never above max_stake).', 'None lost (max_stake binds).', 'It uses raw hit rate and payoff with no shrinkage. At n = 5 a hit-rate estimate is +/- 22 points (1 sigma), so the multiplier is noise until n ~ 30, and the edge-scaled cap already handles small samples properly.', 'Directly gameable: request 2x to get 1x. An honest steward is penalized, and a gaming one isn''t.', 'edge-max-stake.', false, 'docs/rules/confidence-multiplier.md', '2026-09-26'::date, '2026-12-26'::date),
  ('outcome-rescore-confidence', 'Outcome re-score of thesis confidence (Beta on hit rate; cap 60 / demote at n >= 5 with negative P/L)', 'Tempers a steward''s stated confidence with realized outcomes. Feeds the QUANTANAMO >= 80 gate and hardening/forming status.', 'confidence = (10 x stated + wins) / (10 + n). If n >= 5 and summed P/L < 0: cap at 60 and demote hardening -> forming. `private.outcome_posterior_confidence`.', array['supabase/schemas/11_outcome_rescore_sizing.sql']::text[], 'in_force', 'amend', 'Amend (recommended), but it changes which theses pass David''s 80 gate, so it isn''t shipped. Amendment: Proposed: confidence = stated tempered by P(mean return > 0) from the same shrunken moments as edge-max-stake (including backtest credit). Demote only when the upper bound is below zero (mean + sd/sqrt(n) < 0) or n >= 10 with mean < 0.', 'Current rule: large (blocks asymmetric theses permanently).', 'Current rule: small.', 'Five trades can''t tell a Sharpe-0.1 thesis from zero: P(sum < 0) = Phi(-0.1 sqrt 5) = 41%. A hit-rate Beta prior ignores payoff asymmetry.', 'Pushes a steward toward high-hit-rate, low-payoff trades (take profits early, let losers run) just to keep confidence high: the opposite of what compounds.', 'quantanamo-80-gate, edge-max-stake, backtest-evidence-credit.', true, 'docs/rules/outcome-rescore-confidence.md', '2026-09-26'::date, null),
  ('quantanamo-80-gate', 'QUANTANAMO autonomous-entry gate: hardening thesis at confidence >= 80', 'David approves anything below 80; autonomy only for strong theses.', '`steward_sizing_guidance`: QUANTANAMO entry_allowed needs status = hardening and confidence >= 80.', array['supabase/schemas/22_edge_scaled_stake.sql', 'docs/scheduled-run-prompt.md']::text[], 'in_force', 'uphold', 'Uphold (David''s call). Flag two fixes for David: gate on evidence (re-score on expectancy), and at n = 0 require David''s approval or backtest credit, not self-stated confidence. Amendment: None shipped.', 'High for asymmetric theses.', 'Low-moderate (size already bounded).', 'At n = 0 the gate reads the steward''s self-stated number: 80 is a claim, not a measurement.', 'A steward can state 85 on a brand-new thesis and pass. A steward can''t earn its way to 80 with an asymmetric winner.', 'outcome-rescore-confidence, new-thesis-escape.', true, 'docs/rules/quantanamo-80-gate.md', '2026-09-26'::date, null),
  ('required-invalidation', 'Required invalidation on entry (guidance + table trigger)', 'Every lot has a written, priced falsifier before money goes in, so exits aren''t improvised.', 'Guidance returns missing_invalidation without p_invalidation_price > 0. `private.require_lot_invalidation` rejects a new or re-opened open lot without one.', array['supabase/schemas/22_edge_scaled_stake.sql']::text[], 'in_force', 'uphold', 'Uphold. Amendment: Follow-up (not shipped): entry-price sanity check.', 'None.', 'Moderate (process).', 'n/a (process rule).', 'A steward could set an absurdly far invalidation. Guidance only checks > 0, and the ODDSBORNE script checks 0 < inval < price. Follow-up: pass the entry price to guidance so it can reject inval >= entry for longs.', 'regular-session-invalidation, starter-stake.', false, 'docs/rules/required-invalidation.md', '2026-09-26'::date, '2027-03-26'::date),
  ('regular-session-invalidation', 'Equity invalidation exits fire only on regular-session prints', 'Avoid full-lot exits on thin pre/after-hours prints; those set review_at_open instead.', 'Monitor policy autonomous-position-v5, `private.is_us_regular_session` with the NYSE holiday/early-close calendar. Coins and PM are 24/7, with no session filter.', array['workers/research/src/position-decision.ts', 'supabase/schemas/29_us_market_calendar.sql', 'packages/contracts/src/market-calendar.ts']::text[], 'in_force', 'uphold', 'Uphold. Amendment: None.', 'None.', 'Neutral.', 'Extended-hours prints are few, wide-spread trades; a single print isn''t a price.', 'None.', 'required-invalidation.', false, 'docs/rules/regular-session-invalidation.md', '2026-09-26'::date, '2027-03-26'::date),
  ('stale-book-6h', 'Entries need a book observation <= 6 hours old', 'Sizing uses the real book and cash, not a stale snapshot (a stale high book would oversize).', 'Guidance returns stale_book when the older of the equity and cash observations is > 360 minutes old.', array['supabase/schemas/22_edge_scaled_stake.sql']::text[], 'in_force', 'uphold', 'Uphold. Amendment: None.', '~0.', 'Small-moderate.', 'n/a.', 'None; the fix is one snapshot write.', 'starter-stake, drawdown-scaling (both read the book).', false, 'docs/rules/stale-book-6h.md', '2026-09-26'::date, '2027-03-26'::date),
  ('thesis-status-blocks', 'Killed, rejected or unknown thesis blocks new entries', 'A falsified or rejected idea (or a typo''d id) can''t size an entry.', 'Guidance: unknown_thesis, thesis_rejected, thesis_killed; sized_notional = 0.', array['supabase/schemas/21_unknown_thesis_gate.sql', 'supabase/schemas/22_edge_scaled_stake.sql']::text[], 'in_force', 'uphold', 'Uphold. Amendment: None.', 'None.', 'Moderate.', 'n/a.', 'Can''t be escaped by tagging with a non-existent id.', 'new-thesis-escape.', false, 'docs/rules/thesis-status-blocks.md', '2026-09-26'::date, '2027-03-26'::date),
  ('cash-only-no-margin', 'Cash only: no margin, no leverage', 'Worst case is losing the stakes. The book can''t go negative or be force-liquidated.', 'sized_notional <= spendable cash (min(cash, buying power)); the broker rejects buys needing margin.', array['supabase/schemas/14_no_position_cap.sql', 'workers/broker/src/robinhood-broker-agent.ts']::text[], 'in_force', 'uphold', 'Uphold. Amendment: None.', 'Small.', 'Large (eliminates negative-equity paths).', 'n/a.', 'None.', 'portfolio-exposure.', false, 'docs/rules/cash-only-no-margin.md', '2026-09-26'::date, '2027-03-26'::date),
  ('listed-equity-registry', 'Listed-equity registry exempts real tickers from the ontology junk filter', 'Real tickers (TXN, GFS, MP) aren''t discarded as junk words.', '`public.listed_equities`, checked by `private.ontology_label_is_junk` / `isJunkOntologyLabel`.', array['supabase/schemas/26_listed_equities.sql']::text[], 'in_force', 'uphold', 'Uphold. Amendment: None.', 'Negative (helps).', 'None.', 'n/a.', 'Only verified listings are added.', 'None.', false, 'docs/rules/listed-equity-registry.md', '2026-09-26'::date, '2027-03-26'::date),
  ('entry-cap-snapshot', 'Cap-at-entry snapshot and ledger watchdog', 'Every entry is audited against the cap in force when it was made. Breaches and missing invalidations surface twice a day.', '`max_stake_at_entry` trigger; `v_ledger_integrity` (entry_over_max_stake at > 1.10x); `v_invalidation_breaches`; `v_open_lots_missing_invalidation`; `v_ledger_watchdog`.', array['supabase/schemas/24_ledger_watchdog.sql', 'supabase/schemas/30_max_stake_at_entry.sql']::text[], 'in_force', 'uphold', 'Uphold. Amendment: None.', 'None.', 'Detective.', 'n/a.', 'Makes bypass visible.', 'edge-max-stake.', false, 'docs/rules/entry-cap-snapshot.md', '2026-09-26'::date, '2027-03-26'::date),
  ('backtest-evidence-credit', 'Out-of-sample backtest evidence counts toward proven edge', 'Caps shouldn''t wait for 10 live trades when a thesis has real out-of-sample evidence.', '`public.thesis_backtest_evidence` (one active row per thesis; out_of_sample and costs_included required; linked to a `strategy_tests` row with status survived and deflated Sharpe > 0). It adds min(0.5 x n, 20) effective trades, with its mean return haircut 50%, to the thesis''s live moments in `private.edge_max_stake`.', array['supabase/schemas/36_court_rulings.sql']::text[], 'proposed', 'amend', 'Enact with conservative parameters. Amendment: New rule (migration 36).', 'Negative (speeds proof).', 'Neutral-slightly negative (quantified above).', 'Weight 0.5 and a 50% mean haircut are standard discounts for backtest optimism (selection and overfitting). Only out-of-sample, cost-inclusive results from a surviving strategy test with deflated Sharpe > 0 count.', 'A steward could cherry-pick a backtest. That''s mitigated by requiring out_of_sample = true, a linked surviving strategy_tests row, the haircut and the limit, and the rows are auditable on the desk.', 'edge-max-stake, outcome-rescore-confidence.', false, 'docs/rules/backtest-evidence-credit.md', '2026-09-26'::date, '2026-11-26'::date),
  ('portfolio-exposure', 'Portfolio-level exposure / correlation budget', 'Per-entry caps don''t bound total or correlated exposure across open lots.', 'Not in force. Options below.', '{}'::text[], 'proposed', 'amend', 'Proposed; David decision. Options: (a) none (today); (b) open risk-to-invalidation budget <= R% of book (R = 6% or 10%; today 3.1% passes); (c) per-theme open cost <= X% of book (X = 40% would block adds to earnings_gap_structure, at 46% via CODA). Amendment: None shipped.', 'Depends on option.', 'Depends on option.', 'Needs a correlation estimate by theme; with n this small, use theme membership as the proxy.', 'Without it, a steward can stack correlated starters across several theses.', 'cash-only-no-margin, new-thesis-escape.', true, 'docs/rules/portfolio-exposure.md', '2026-09-26'::date, null),
  ('shadow-exits', 'Shadow (paper) exit tracking', 'Test alternative exit rules without trading them. Promote a rule only once it beats real exits.', '`meta.paper_<rule>` on lot rows; `v_shadow_exits`, `v_shadow_exit_scorecard` (promotable at n >= 10 and LCB of paper - real > 0).', array['supabase/schemas/32_shadow_exits.sql', 'supabase/schemas/33_shadow_exits_definer.sql']::text[], 'in_force', 'uphold', 'Uphold. Amendment: None.', 'None.', 'None.', 'Same LCB bar as the stake rule; n = 4 today for bank_at_+20pct (LCB -10.5 pts).', 'Promotion is by evidence.', 'None.', false, 'docs/rules/shadow-exits.md', '2026-09-26'::date, '2026-11-26'::date)
